/**
 * Every sentence that four rounds of independent review wrote to test the rule-based text checks, each with the outcome
 * the reviewers expect. tests/unit/claims-corpus.test.ts reads each one through the same save path its round used.
 *
 *  - 'promise' and 'honest-contract': the terms an agency writes into the service contract (the Services field,
 *    termsIssue, and findContractClaims): a promise of a result must be refused, honest contract wording must pass.
 *  - 'advance' and 'honest-payment': payment terms (the agency's Payment terms, termsIssue, and a client's own,
 *    clientTermsIssue): payment asked for before the work (15 U.S.C. § 1679b(b)) must be refused, honest terms must pass.
 *  - 'prediction' and 'ordinary': AI answers of the credit guide (findGeneratedClaims): a prediction of a result must
 *    be refused, an ordinary explanation must pass.
 *
 * corpus: 'r1' (the first round's probes: a1 removal promises, a2 advance fees, a3 habitual predictions, a5 removal
 * nouns and gerunds, a6 false positives), 'r2' (the second round), 'r3' (the third), 'r4' (the fourth, read like the
 * third: the same base terms and save paths). Each row is [source, text] or
 * [source, text, false]: the probe and group or the reviewer's tag, the sentence, and false for a sentence written to slip
 * through one exemption (natural: false, "abuse"); every other sentence is wording an agency or a model would plausibly
 * write.
 */
export type CorpusClass = 'promise' | 'honest-contract' | 'advance' | 'honest-payment' | 'prediction' | 'ordinary';
export interface CorpusSentence {
  text: string;
  expect: 'refuse' | 'pass';
  cls: CorpusClass;
  corpus: 'r1' | 'r2' | 'r3' | 'r4';
  /** false for a sentence written to slip through one exemption. */
  natural: boolean;
  source: string;
}

const group = (corpus: CorpusSentence['corpus'], cls: CorpusClass, expect: CorpusSentence['expect'], rows: [source: string, text: string, natural?: false][]): CorpusSentence[] =>
  rows.map(([source, text, natural]) => ({ text, expect, cls, corpus, natural: natural ?? true, source }));

